preConditionHook:
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, thereafter
// carrying S += TrueRange - TrueRange[Length], re-seeding when the length
// changes. Same block as AtrProfitTarget, ClimaxBar and BarRangeAtrMultiple,
// including the TWO separate accumulator statements -- EasyLanguage evaluates
// Summation[1] + Price - Price[Length] left to right, and folding it to
// S += in - out rounds differently and lands on the other side of a threshold.
// The accumulator stays in the hook, which the generator emits unconditionally:
// EasyLanguage does not short-circuit and/or, so a stateful call in a condition
// would advance every bar in EL and only on some bars in C++.
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLenState = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLookback;
// One ATR value for the whole window, read at the CURRENT bar. The EL twin
// writes the count as an explicit loop rather than CountIF precisely so the ATR
// is not re-evaluated at each counted offset -- CountIF's argument is a true
// series and would shift the function call with it. The count is otherwise
// identical: bars 0..lookback-1, current bar INCLUDED.
// Direction-agnostic, so both sides read the same count; Brooks's 'not many
// large bars appear' is this rule negated, a per-placement toggle.
// largeCount is a class member and persists across bars, so it is reset first.
largeCount = 0.0;
for (int k = 0; k < (int)lookback; ++k) {
    if (el_ge(high[k] - low[k], largeMultiple * atrValue)) {
        largeCount = largeCount + 1;
    }
}
